  let best=null;for(const m of getLegal(ng)){const to=sq(m.tr,m.tc);const d=dist[to];if(d==null)continue;const cd=ctr(m.tr,m.tc);if(!best||d<best.d||(d===best.d&&cd<best.cd))best={mv:m,to,d,cd};}
