/* #550 HEX-T-13: a lesson note as a hint in words - the move's own name left out, since the hint asks the player to find it. Removes the SAN
   (with any move number and !?+# marks) wherever it stands as a word, then tidies the leftover punctuation. '' when nothing is left. */
function lessonHintWords(note,san){let t=String(note||'').trim();const m=cleanSAN(String(san||''));if(!t||!m)return '';
  const esc=m.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');t=t.replace(new RegExp('(^|[\\s(\u2014\u2013-])(?:\\d+\\.+\\s*)?'+esc+'[+#!?]*(?=$|[\\s,.;:)!?\u2014\u2013-])','g'),'$1');
  t=t.replace(/\(\s*\)/g,'').replace(/\s{2,}/g,' ').replace(/^[\s,.;:!?\u2014\u2013-]+/,'').trim();if(!/[A-Za-z]{3}/.test(t))return '';
  return '\u{1F4A1} '+t.charAt(0).toUpperCase()+t.slice(1)+(/[.!?]$/.test(t)?'':'.');}
function cleanSAN(s){return s.replace(/[+#!?]/g,'').replace(/0-0-0/gi,'O-O-O').replace(/0-0/gi,'O-O').replace(/e\.p\.?/gi,'').trim();}

function parsePGN(pgn){
  let t=pgn.replace(/\[[^\]]*\]/g,' ');       // tag headers
  t=t.replace(/\{[^}]*\}/g,' ');              // {comments}
  t=pgnStripLineComments(t);                  // ';' comments and '%' escape lines, AFTER tags and {}: a ';' inside either is text (#549 A3-R4: they leaked words as moves)
  t=t.replace(/\([^()]*\)/g,' ');             // (variations) – simple
  t=t.replace(/\$\d+/g,' ');                  // $NAGs
  t=t.replace(/\d+\.(\.\.)?/g,' ');           // move numbers 12. / 12...
  t=t.replace(/\b(1-0|0-1|1\/2-1\/2|\*)\b/g,' '); // results
  t=t.replace(/0-0-0/g,'O-O-O').replace(/0-0/g,'O-O'); // zero-castling -> letter O (else the filter below drops it and desyncs the game)
  t=t.replace(/[\u2654\u265A]/g,'K').replace(/[\u2655\u265B]/g,'Q').replace(/[\u2656\u265C]/g,'R').replace(/[\u2657\u265D]/g,'B').replace(/[\u2658\u265E]/g,'N'); // figurine pieces -> letters
  return t.trim().split(/\s+/).filter(x=>x.length>0&&/[a-hKQRBNO]/.test(x));
}

// Also pull the player names / result for display
// #348: ISO country code -> flag. #550 (Kunal, 12 Nov, his screenshot of the Review board in Chrome on Windows: "T on top on the white
// background with white text is very hard to see"): the flag was a regional-indicator emoji, and Windows draws no flag emoji, so it showed as
// pale letters (AT, US) on the white player's bar. It is now a small picture from the app's own files (flags/<key>.png, 60x45, rendered from
// flag-icons 7.2.3, MIT, flags/LICENSE-flag-icons.txt), the same on every system. flagOf returns the file key, or '' for no flag.
const FLAG_KEYS=new Set('ad ae af ag ai al am ao aq ar as at au aw ax az ba bb bd be bf bg bh bi bj bl bm bn bo bq br bs bt bv bw by bz ca cc cd cf cg ch ci ck cl cm cn co cp cr cu cv cw cx cy cz de dg dj dk dm do dz ec ee eg eh er es et eu fi fj fk fm fo fr ga gb gd ge gf gg gh gi gl gm gn gp gq gr gs gt gu gw gy hk hm hn hr ht hu ic id ie il im in io iq ir is it je jm jo jp ke kg kh ki km kn kp kr kw ky kz la lb lc li lk lr ls lt lu lv ly ma mc md me mf mg mh mk ml mm mn mo mp mq mr ms mt mu mv mw mx my mz na nc ne nf ng ni nl no np nr nu nz om pa pc pe pf pg ph pk pl pm pn pr ps pt pw py qa re ro rs ru rw sa sb sc sd se sg sh si sj sk sl sm sn so sr ss st sv sx sy sz tc td tf tg th tj tk tl tm tn to tr tt tv tw tz ua ug um un us uy uz va vc ve vg vi vn vu wf ws xk ye yt za zm zw'.split(' '));
function flagOf(cc){
  if(!cc||cc.length!==2||!/^[A-Za-z]{2}$/.test(cc))return '';
  const u=cc.toUpperCase();
  // chess.com's user-assigned codes: XE England, XS Scotland, XW Wales have flags of their own; XX (International) and the other
  // user-assigned pairs (AA, QM..QZ, XA..XZ, ZZ) have none, except XK, which chess.com and flag-icons both use for Kosovo.
  if(u==='XE')return 'gb-eng';if(u==='XS')return 'gb-sct';if(u==='XW')return 'gb-wls';
  const k=u.toLowerCase();return FLAG_KEYS.has(k)?k:'';
}
// #353 Imported accounts and their games, kept for good and across reloads. Bounded so a long
// history cannot fill the origin's storage: 8 accounts, ACCT_GMAX games each, oldest account
// dropped first. A quota failure keeps the games in memory for this session rather than losing
// the fetch.
// #431 ACCT_GMAX was 40 and the chess.com fetch asked for ONE month, so a player who had not
// played this month saw an EMPTY Review list (Kunal, twice: "Why are there only 47 games in
// review. There should be thousands."). A cap is still correct here - the public API serves one
// month per request, the rows carry full PGNs and localStorage is ~5MB for the whole app - so
// the fix is a bigger cap and a fetch that does not let the calendar set the number, not an
// unbounded list. ACCT_GMONTHS bounds the request count: at most one request per month walked.
// US-R25 requires ACCT_GMAX to be STATED ON SCREEN, so it is rendered, never retyped.
// #432 ACCT_GMAX IS NOT THE ONLY LIMIT AND #431 STATED IT AS IF IT WERE. The walk stops on
// whichever of the two bounds it reaches first, and for a THIN BUT LONG history - a few games a
// month for years, the ordinary shape - that is ACCT_GMONTHS, not ACCT_GMAX. Both antagonists
// found it independently from different doors: 24 months x 5 games = 120 on the account, 30 rows
// shown, under a sentence reading "Showing up to 200 games per account." US-R25 asks for a list
// "bounded only by a limit the app STATES on screen", and in that state it was bounded by one it
// did not. So the fetch RECORDS which bound stopped it and the screen states that one.
// Kept in its own tiny key rather than on the rows or beside them in ACCT_G: one short string per
// account cannot move the byte budget that TC-R35(iii) and gate 61's A4b measure over ACCT_G.
// #433 CORRECTION: the paragraph below says "no pre-#431 store can ever reach 200" and infers from that
