const DRILL_GRADES=['Mistake','Blunder','Miss'];
function drillGrade(lab){const t=String(lab||'').trim();const i=DRILL_GRADES.findIndex(g=>g.toLowerCase()===t.toLowerCase());return i>=0?DRILL_GRADES[i]:'mistake';}
