// The position's book key: FNV-1a 32 over 'board side castling' of its FEN, seven base-36 digits. gates/opening-book/build.js writes
// BOOK_POS with this very function (read out of this file), so the table and the lookup cannot use two different keys.
function bookKey(game){const f=toFEN(game).split(' '),s=f[0]+' '+f[1]+' '+f[2];let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}return h.toString(36).padStart(7,'0');}
let _bookSet=null;
function bookHas(game){if(!_bookSet){_bookSet=new Set();for(let i=0;i+7<=BOOK_POS.length;i+=7)_bookSet.add(BOOK_POS.slice(i,i+7));}return _bookSet.has(bookKey(game));}
// The last of plies 1..cap whose resulting position is a named opening position (positions: loadSANs' list, positions[0] the start).
function bookTablePlies(positions,cap){let last=0;const n=Math.min(cap,positions?positions.length-1:0);for(let i=1;i<=n;i++){try{if(bookHas(positions[i]))last=i;}catch(e){}}return last;}
// The lesson library's lines as a move prefix (reading (1)). `openings` is the OPENINGS list; read off window here and not off the
// OPENINGS constant so gates/engine-extract.js can run this function over lessons.js's list in Node.
function lessonBookPlies(playedSans,openings){
  const played=playedSans.map(cleanSAN);
  let best=0;
  const consider=(line)=>{if(!line||!line.length)return;let k=0;const n=Math.min(line.length,played.length);while(k<n&&played[k]===cleanSAN(line[k]))k++;if(k>best)best=k;};
  // #549 antagonist B final read (B5-F): an opening may pin how much of its line counts as book (bookPlies), so folding a longer
  // line into a lesson (job 65's Petroff) does not move the Book count of games that were reviewed before it.
  for(const op of (openings||[])){consider(op.bookPlies>0?(op.line||[]).slice(0,op.bookPlies):op.line);if(op.vars)for(const v of op.vars)consider(v.line);}
  return best;
}
// How many leading plies of the game are Book: the larger of the two readings above, at most 24.
function openingBookPlies(playedSans,positions,openings,table){
  const O=openings||((typeof window!=='undefined'&&window.CTLESSONS&&window.CTLESSONS['OPENINGS'])||[]);   // the OPENINGS list; by string so engine-extract's reference scan does not take the property for the constant
  const T=table===undefined?BOOK_TABLE:table;
  return Math.min(24,Math.max(lessonBookPlies(playedSans,O),T?bookTablePlies(positions,24):0));
}
const BOOK_POS='';
/* #368 y17b. The Skills panel, the third thing in Kunal's chess.com recording: counters per category, built
   from the game just reviewed. Every number here is COUNTED off the board, never estimated, and every row that
   points at moves keeps their ply indexes so the summary can jump to them. Pure: positions (N+1), plies (N,
   with .move and .san), out (the analysis array, may lack motifs on the fallback engine), bookN.
   develop: of the side's first ten moves, how many brought a knight or bishop off its home square for the
     first time, or castled. castled: the side's move number, or null. checksFaced: checks the side had to
     answer. weakPawns: doubled (each extra) plus isolated pawns in the FINAL position. book: plies inside the
     lesson library's lines. forks: the side's moves that forked (moveMotifs). forksMissed: the engine's move
     was a fork and the side lost >= 50cp playing something else. hanging: the side's move lost >= 100cp, was
     not a sacrifice the engine liked, and left a piece the opponent wins >= 2 pawns of material on (seeSq).
     rookFiles: rook moves sideways onto a file with none of the side's own pawns. */
function gameSkills(positions,plies,out,bookN,plyBase){
  const mk=()=>({develop:{n:0,of:0},castled:null,checksFaced:0,weakPawns:0,book:0,forks:[],forksMissed:[],hanging:[],rookFiles:[]});
  const S={w:mk(),b:mk()};
  try{
    const home={w:{'7,1':1,'7,2':1,'7,5':1,'7,6':1},b:{'0,1':1,'0,2':1,'0,5':1,'0,6':1}};
    const left={w:{},b:{}};
    const N=plies.length;
    for(let i=0;i<N;i++){
      const pos=positions[i];const mv=plies[i]&&plies[i].move;if(!pos||!mv)continue;
      const side=pos.turn,them=side==='w'?'b':'w',s=S[side];
      const pc=pos.board[mv.fr]&&pos.board[mv.fr][mv.fc];if(!pc)continue;
      const moveNo=Math.floor(((plyBase||0)+i)/2)+1;   // #549 item (66): from the game's own start
      const isCastle=pc.t==='k'&&Math.abs(mv.tc-mv.fc)===2;
      const key=mv.fr+','+mv.fc;
      if(moveNo<=10){s.develop.of++;const out1=(pc.t==='n'||pc.t==='b')&&home[side][key]&&!left[side][key];if(isCastle||out1)s.develop.n++;}
      if((pc.t==='n'||pc.t==='b')&&home[side][key])left[side][key]=1;
      if(isCastle&&s.castled==null)s.castled=moveNo;
      const san=(plies[i].san||'');if(/[+#]/.test(san))S[them].checksFaced++; /* #371 (X-11): the mating check is a check */
      if(i<bookN)s.book++;
      const a=out[i]||{};
      let mo=a.motifs;if(!mo){try{mo=moveMotifs(pos,mv);}catch(e){mo=[];}}
      if(mo.indexOf('fork')>=0)s.forks.push(i);
      else if(a.bestMove&&(a.loss||0)>=50){try{if(moveMotifs(pos,a.bestMove).indexOf('fork')>=0)s.forksMissed.push(i);}catch(e){}}
      const L=a.cls&&a.cls.label;
      if((a.loss||0)>=100&&L!=='Brilliant'&&L!=='Great'){const p2=positions[i+1];if(p2){let hung=false;
        for(let r=0;r<8&&!hung;r++)for(let c=0;c<8&&!hung;c++){const q=p2.board[r][c];if(q&&q.c===side&&q.t!=='k'&&q.t!=='p'){try{if(seeSq(p2,r,c,them)>=2)hung=true;}catch(e){}}}
        if(hung)s.hanging.push(i);}}
      if(pc.t==='r'&&mv.fc!==mv.tc){const nb=applyMove(pos.board,mv);let pawns=0;for(let r=0;r<8;r++){const q=nb[r][mv.tc];if(q&&q.t==='p')pawns++;}if(pawns===0)s.rookFiles.push(i);} /* #371 (X-11): open means no pawn of EITHER colour */
    }
    const fin=positions[N]||positions[N-1];
    if(fin){for(const side of ['w','b']){const f=[0,0,0,0,0,0,0,0];for(let r=0;r<8;r++)for(let c=0;c<8;c++){const q=fin.board[r][c];if(q&&q.t==='p'&&q.c===side)f[c]++;}
      let weak=0;for(let c=0;c<8;c++){if(f[c]>=2)weak+=f[c]-1;if(f[c]>0&&(c===0||f[c-1]===0)&&(c===7||f[c+1]===0))weak+=1;}S[side].weakPawns=weak;}}
  }catch(e){}
  return S;
}
// Pull a capped list of SAN tokens out of a PGN movetext (enough for opening identification).
function pgnSans(pgn,max){
  if(!pgn)return [];
  let t=String(pgn).replace(/\{[^}]*\}/g,' ').replace(/\([^)]*\)/g,' ').replace(/\[[^\]]*\]/g,' ').replace(/\$\d+/g,' ');
  t=t.replace(/\b\d+\.(\.\.)?/g,' ').replace(/(1-0|0-1|1\/2-1\/2|\*)/g,' ');
  const out=[];
  for(const tok of t.split(/\s+/)){if(!tok)continue;if(/^O-O(-O)?[+#]?$/.test(tok)||/^[KQRBNa-h][a-h0-8xKQRBN=+#!?-]*$/.test(tok)){out.push(tok);if(max&&out.length>=max)break;}}
  return out;
}
