          <button onClick={()=>setPzCelebrate(null)} style={{...btn('var(--ac)','none','var(--acInk,#0b0d10)'),width:'100%',fontWeight:800,fontSize:'clamp(14px,3.2vw,16px)'}}>Continue ▶</button>
